import React, { useState } from 'react';

// ── Seeded RNG ────────────────────────────────────────────────────
function seededRng(id) {
  let h = 2166136261;
  for (let i = 0; i < id.length; i++) {
    h ^= id.charCodeAt(i);
    h = Math.imul(h, 16777619) >>> 0;
  }
  return () => { h ^= h << 13; h ^= h >> 17; h ^= h << 5; return (h >>> 0) / 0xFFFFFFFF; };
}

// ── Colour helpers ────────────────────────────────────────────────
function darken(hex, amt = 0.35) {
  const r = parseInt(hex.slice(1,3),16), g = parseInt(hex.slice(3,5),16), b = parseInt(hex.slice(5,7),16);
  return `rgb(${Math.round(r*(1-amt))},${Math.round(g*(1-amt))},${Math.round(b*(1-amt))})`;
}
function lighten(hex, amt = 0.55) {
  const r = parseInt(hex.slice(1,3),16), g = parseInt(hex.slice(3,5),16), b = parseInt(hex.slice(5,7),16);
  return `rgb(${Math.min(255,Math.round(r+(255-r)*amt))},${Math.min(255,Math.round(g+(255-g)*amt))},${Math.min(255,Math.round(b+(255-b)*amt))})`;
}

// ── Loeb-style cover system ───────────────────────────────────────
// Green for Greek, Red for Latin — here we use subject classification
// The book's own colour determines the binding tone
// All covers are identical in format — only colour and title change

// ── Marbled endpaper pattern — bold, blob-forward like real marbling
// Inspired by the reference image: large colour masses with cream veining between
function MarbledSVG({ id, color, w = 120, h = 160 }) {
  const rng = seededRng(id + 'mrb2');

  // Extract RGB from hex for colour mixing
  const r0 = parseInt(color.slice(1,3),16);
  const g0 = parseInt(color.slice(3,5),16);
  const b0 = parseInt(color.slice(5,7),16);

  // Generate a rich palette from the book colour — dark, mid, light, complementary
  const dark   = `rgb(${Math.round(r0*0.45)},${Math.round(g0*0.45)},${Math.round(b0*0.45)})`;
  const mid    = `rgb(${Math.round(r0*0.72)},${Math.round(g0*0.65)},${Math.round(b0*0.60)})`;
  const light  = `rgb(${Math.min(255,Math.round(r0*1.1+40))},${Math.min(255,Math.round(g0*0.9+20))},${Math.min(255,Math.round(b0*0.7+10))})`;
  const gold   = `rgb(${Math.min(255,Math.round(r0*0.9+60))},${Math.min(255,Math.round(g0*0.75+50))},${Math.round(b0*0.3+20)})`;
  const cream  = '#f5f0e4';

  // Large blobs — the dominant colour masses (like the red and blue in the photo)
  const blobs = Array.from({ length: 14 }, (_, i) => {
    const palettes = [dark, dark, mid, mid, light, gold, dark, mid, light, dark, mid, gold, dark, mid];
    return {
      cx: rng() * w,
      cy: rng() * h,
      rx: w * (0.12 + rng() * 0.22),
      ry: h * (0.08 + rng() * 0.18),
      rot: rng() * 360,
      fill: palettes[i % palettes.length],
      op: 0.72 + rng() * 0.25,
    };
  });

  // Combed lines — the raked/combed effect that gives marbling its character
  const combs = Array.from({ length: 8 }, (_, i) => {
    const x = w * (i / 8) + rng() * (w/10);
    return { x, wavy: Array.from({length:12}, (_,j) => ({
      y: h*(j/11),
      dx: (rng()-0.5)*14,
    }))};
  });

  // Build comb path
  const combPaths = combs.map(c => {
    const pts = c.wavy.map((p,j) => `${j===0?'M':'L'}${c.x+p.dx},${p.y}`).join(' ');
    return pts;
  });

  return (
    <svg width={w} height={h} xmlns="http://www.w3.org/2000/svg" style={{display:'block',flexShrink:0}}>
      <defs>
        <filter id={`blur-${id}`}><feGaussianBlur stdDeviation="3.5"/></filter>
        <filter id={`blur2-${id}`}><feGaussianBlur stdDeviation="1.2"/></filter>
        <clipPath id={`clip-${id}`}><rect width={w} height={h}/></clipPath>
      </defs>
      {/* Cream base */}
      <rect width={w} height={h} fill={cream}/>
      {/* Large blurred colour masses */}
      <g clipPath={`url(#clip-${id})`} filter={`url(#blur-${id})`}>
        {blobs.map((b,i) => (
          <ellipse key={i} cx={b.cx} cy={b.cy} rx={b.rx} ry={b.ry}
            transform={`rotate(${b.rot},${b.cx},${b.cy})`}
            fill={b.fill} opacity={b.op}/>
        ))}
      </g>
      {/* Sharper secondary layer for depth */}
      <g clipPath={`url(#clip-${id})`} filter={`url(#blur2-${id})`}>
        {blobs.slice(0,7).map((b,i) => (
          <ellipse key={'s'+i} cx={b.cx+w*0.08} cy={b.cy+h*0.06} rx={b.rx*0.55} ry={b.ry*0.55}
            transform={`rotate(${b.rot+45},${b.cx},${b.cy})`}
            fill={b.fill} opacity={0.45}/>
        ))}
      </g>
      {/* Combed lines — the defining marbling technique */}
      <g clipPath={`url(#clip-${id})`} opacity={0.18}>
        {combPaths.map((p,i) => (
          <path key={i} d={p} fill="none" stroke={cream} strokeWidth={0.8}/>
        ))}
      </g>
      {/* Cream veining — light lines between colour masses */}
      {blobs.slice(0,5).map((b,i) => (
        <ellipse key={'v'+i}
          cx={b.cx + (rng()-0.5)*w*0.1} cy={b.cy + (rng()-0.5)*h*0.1}
          rx={b.rx*0.18} ry={b.ry*0.12}
          transform={`rotate(${b.rot},${b.cx},${b.cy})`}
          fill={cream} opacity={0.5}/>
      ))}
    </svg>
  );
}

// ── Loeb spine label box ──────────────────────────────────────────
function LabelPlate({ title, author, year, gold }) {
  return (
    <div style={{ position:'absolute', top:'50%', left:'50%', transform:'translate(-50%,-50%)', width:'76%', border:`1px solid ${gold}`, padding:'6px 7px', background:'rgba(0,0,0,0.18)', textAlign:'center', boxSizing:'border-box' }}>
      <div style={{ borderBottom:`0.5px solid ${gold}`, marginBottom:4, paddingBottom:4, opacity:0.7 }}/>
      <div style={{ fontSize:9.5, fontWeight:700, color:gold, fontFamily:'var(--font-display)', letterSpacing:'0.02em', lineHeight:1.3, fontStyle:'italic', marginBottom:3, textShadow:'0 1px 3px rgba(0,0,0,0.5)' }}>
        {title}
      </div>
      <div style={{ borderTop:`0.5px solid ${gold}`, marginTop:3, paddingTop:4, opacity:0.7 }}/>
      {author && <div style={{ fontSize:7.5, color:gold, opacity:0.8, fontStyle:'italic', lineHeight:1.2, fontFamily:'var(--font-serif)' }}>{author}</div>}
    </div>
  );
}

// ── BookCard — Loeb Classical Library style ───────────────────────
// Solid colour binding, marbled top strip, gold label plate, gold rules
export function BookCard({ book, status, onClick, selected }) {
  const [hovered, setHovered] = useState(false);
  const id     = book.id || book.title;
  const color  = book.color || '#7a5c38';
  const binding = darken(color, 0.28);   // aged leather tone
  const gold    = lighten(color, 0.62);  // gold lettering
  const pct = book.pages ? Math.min(100,Math.round((book.progress/book.pages)*100)) : 0;

  return (
    <div onClick={onClick}
      onMouseEnter={() => setHovered(true)}
      onMouseLeave={() => setHovered(false)}
      style={{ width:120, flexShrink:0, cursor:'pointer', position:'relative',
        transform: hovered ? 'translateY(-7px) rotate(-0.5deg)' : 'translateY(0)',
        transition: 'transform 0.2s cubic-bezier(.2,.8,.3,1)',
        filter: selected ? `drop-shadow(0 0 6px ${color}88)` : 'none',
      }}>
      <div style={{ borderRadius:'2px 3px 3px 2px', overflow:'hidden',
        boxShadow: hovered
          ? `3px 8px 22px rgba(0,0,0,0.32), -1px 0 0 rgba(0,0,0,0.18), inset -3px 0 6px rgba(0,0,0,0.12)`
          : `2px 4px 12px rgba(0,0,0,0.22), -1px 0 0 rgba(0,0,0,0.14), inset -2px 0 4px rgba(0,0,0,0.08)`,
        transition:'box-shadow 0.2s',
      }}>

        {/* ── COVER FACE ── */}
        <div style={{ height:160, background:binding, position:'relative' }}>
          {/* Marbled top strip — Loeb-style endpaper peek */}
          <div style={{ height:44, overflow:'hidden', flexShrink:0 }}>
            <MarbledSVG id={id} color={color} w={120} h={44}/>
          </div>
          {/* Gold rule separating marble from binding */}
          <div style={{ height:1, background:gold, opacity:0.7 }}/>
          <div style={{ height:'0.5px', background:gold, opacity:0.3, marginTop:1 }}/>

          {/* Main binding area — solid colour with label plate */}
          <div style={{ position:'absolute', top:48, left:0, right:0, bottom:0 }}>
            {/* Subtle leather texture — gradient */}
            <div style={{ position:'absolute', inset:0, background:`linear-gradient(135deg, rgba(255,255,255,0.04) 0%, transparent 50%, rgba(0,0,0,0.08) 100%)` }}/>

            {/* Gold rules — top and bottom of label area */}
            <div style={{ position:'absolute', top:10, left:8, right:8, height:'0.75px', background:gold, opacity:0.5 }}/>
            <div style={{ position:'absolute', bottom:14, left:8, right:8, height:'0.75px', background:gold, opacity:0.5 }}/>

            {/* Title label plate */}
            <LabelPlate title={book.title} author={book.author} year={book.year} gold={gold}/>

            {/* Left spine shadow */}
            <div style={{ position:'absolute', left:0, top:0, bottom:0, width:5, background:'linear-gradient(to right, rgba(0,0,0,0.28), transparent)' }}/>
          </div>

          {/* Reading progress bar */}
          {book.status === 'reading' && book.pages && pct > 0 && (
            <div style={{ position:'absolute', bottom:0, left:0, width:`${pct}%`, height:2, background:gold, opacity:0.7 }}/>
          )}
        </div>

        {/* Status strip */}
        {status && (
          <div style={{ background:darken(color,0.45), padding:'3px 8px', fontSize:7, color:gold, opacity:0.85, fontFamily:'var(--font-mono)', fontStyle:'normal', letterSpacing:'0.07em', textAlign:'center' }}>
            {status.label.toUpperCase()}
          </div>
        )}
      </div>
    </div>
  );
}

// ── BookSpine ─────────────────────────────────────────────────────
export function BookSpine({ book, height = 120, onClick, selected }) {
  const [hovered, setHovered] = useState(false);
  const id      = book.id || book.title;
  const color   = book.color || '#7a5c38';
  const binding = darken(color, 0.28);
  const gold    = lighten(color, 0.62);
  const w = Math.max(18, Math.min(32, Math.floor(((book.pages||300)/800)*36)+12));

  return (
    <div onClick={onClick}
      title={`${book.title}${book.author?' — '+book.author:''}`}
      onMouseEnter={() => setHovered(true)}
      onMouseLeave={() => setHovered(false)}
      style={{ width:w, height, flexShrink:0, cursor:'pointer',
        transform: hovered ? 'translateY(-6px)' : 'none',
        transition:'transform 0.18s cubic-bezier(.2,.8,.3,1)',
      }}>
      <div style={{ width:'100%', height:'100%', background:binding,
        borderRadius:'2px 3px 3px 2px', overflow:'hidden', position:'relative',
        boxShadow: selected ? `0 0 0 2px ${color}, 2px 3px 10px rgba(0,0,0,0.3)`
          : hovered ? '2px 5px 14px rgba(0,0,0,0.3)' : '1px 2px 6px rgba(0,0,0,0.2)',
        transition:'box-shadow 0.18s',
      }}>
        {/* Marble top strip */}
        <div style={{ height:14, overflow:'hidden' }}>
          <MarbledSVG id={id+'sp'} color={color} w={w} h={14}/>
        </div>
        <div style={{ height:1, background:gold, opacity:0.65 }}/>
        {/* Rotated title */}
        <div style={{ position:'absolute', top:18, bottom:14, left:0, right:0, display:'flex', alignItems:'center', justifyContent:'center' }}>
          <div style={{ writingMode:'vertical-rl', textOrientation:'mixed', transform:'rotate(180deg)',
            fontSize:8.5, fontWeight:600, color:gold, letterSpacing:'0.04em',
            padding:'4px 2px', overflow:'hidden', maxHeight:height-36,
            textOverflow:'ellipsis', whiteSpace:'nowrap', lineHeight:1.2,
            fontFamily:'var(--font-display)', textShadow:'0 1px 2px rgba(0,0,0,0.35)',
          }}>{book.title}</div>
        </div>
        <div style={{ position:'absolute', bottom:8, left:2, right:2, height:'0.75px', background:gold, opacity:0.5 }}/>
        <div style={{ position:'absolute', left:0, top:0, bottom:0, width:3, background:'linear-gradient(to right, rgba(0,0,0,0.25), transparent)' }}/>
      </div>
    </div>
  );
}
